{
  "technical_and_design_decisions": [
    "Implementation language: Go (matching Hyperledger Fabric codebase)",
    "Use fabric-protos-go for all protobuf message definitions",
    "Create a new standalone library package (e.g., github.com/example/fabric-configlib) with no dependency on fabric internal packages (viper, genesisconfig, configtxgen)",
    "For U1: Modify peer validation logic in validation/validation.go to include read-set values in validation; requires changes to transaction simulation and validation phases",
    "For U2-U8: Implement pure functions that operate on protobuf messages; no network access, no filesystem assumptions for key material",
    "Cryptographic operations via bccsp (Fabric's crypto abstraction) or standard Go crypto libraries",
    "Configuration update calculation (U7) will reimplement configtxlator compute_update logic using protobuf reflection",
    "All generated protobufs must be semantically equivalent to existing tooling output (proto.Equal for U2, semantic equivalence for others)",
    "Unit tests will use table-driven tests with golden files from integration test suite",
    "Integration tests will spin up a minimal Fabric network using docker-compose for end-to-end validation"
  ],
  "assumptions": [
    "Developer has deep familiarity with Hyperledger Fabric architecture, protobuf structures, and configtx internals",
    "Existing integration test suite provides prototypical configtx.yaml and MSP folder for golden comparisons",
    "Fabric version target is 2.x (based on release-2.0 tutorial link in U8)",
    "No requirement for backward compatibility with Fabric 1.4",
    "Key material for signing (U3) provided as bccsp.Key or standard crypto.PrivateKey interface",
    "ChannelUpdate/ConfigUpdate messages are already constructed; library only handles signing/assembly",
    "Max_message_count parameter (U5) refers to Orderer.BatchSize.MaxMessageCount in config",
    "Consortium modification (U8) only adds org to existing consortium; does not create new channel",
    "No UI/CLI required; only library functions with specified signatures",
    "Effort estimates assume single developer; no parallelization",
    "Code review and refactoring effort included as separate activity"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1: Read-set value validation implementation",
      "activity_description": "Modify peer validation logic to include read-set values (keys, versions, and values) in validation. Update transaction simulation to capture read-set values, enhance validation to compare read-set values against current world state, and invalidate transactions on mismatch. Includes unit tests and integration tests with tampered world state.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "A2",
      "activity_name": "U2: Data structure adaptation and CreateChannelTx design",
      "activity_description": "Copy and adapt Profile, Application, Orderer, Consortium, Policy, Capabilities structures from fabric genesisconfig package. Design CreateChannelTx function signature with Option pattern. Define internal mapping from adapted structures to configtx protobufs.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: CreateChannelTx implementation",
      "activity_description": "Implement CreateChannelTx function that builds genesis block protobuf from adapted structures. Construct ConfigEnvelope with channel group, orderer group, application group, consortiums, policies, and capabilities. Ensure protobuf encoding matches configtxgen output exactly.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A4",
      "activity_name": "U2: Testing and golden file validation",
      "activity_description": "Write unit tests for CreateChannelTx. Create integration test that generates genesis block from configtx.yaml and MSP folder using both configtxgen and library, then compare with proto.Equal. Handle any discrepancies.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A5",
      "activity_name": "U3: Detached signature generation",
      "activity_description": "Implement function to sign ChannelUpdate transaction and produce detached signature. Accept key material as parameter (bccsp.Key or crypto.PrivateKey). Generate signature over ChannelUpdate payload per Fabric signing specification. Return signature in format suitable for later assembly.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A6",
      "activity_name": "U3: Signature generation testing",
      "activity_description": "Unit tests for detached signature generation. Verify signature validates against public key. Integration test: use generated signature in U4 assembly and verify orderer acceptance.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A7",
      "activity_name": "U4: Config update assembly with signatures",
      "activity_description": "Implement function that takes ConfigUpdate and collection of detached signatures, assembles them into a fully signed Envelope message. Follow Fabric's signature set construction (SignatureHeader + signature). Ensure output matches peer signtx command behavior.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8",
      "activity_name": "U4: Assembly testing",
      "activity_description": "Unit tests for assembly function. Integration test: compare assembled envelope with one built by sequential peer signtx commands. Verify orderer and peer validation acceptance.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "U5: Batch size config update generation",
      "activity_description": "Implement function to generate ConfigUpdate that modifies Orderer.BatchSize.MaxMessageCount. Input: current channel config (or config block) and new max_message_count value. Output: unsigned ConfigUpdate protobuf. Must compute delta correctly using configtxlator-like logic.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A10",
      "activity_name": "U5: Batch size update testing",
      "activity_description": "Unit tests for batch size update generation. Integration test: generate update with library, apply to channel, verify new batch size takes effect. Compare with manual configtxgen/protolator process.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "U6: Organization ConfigGroup generation",
      "activity_description": "Implement function to generate Organization ConfigGroup (MSP, policies, admin principals) from raw cryptographic material (root certs, intermediate certs, admin certs, TLS certs). No dependency on MSP folder structure or cryptogen. Output semantically equivalent to configtxgen -printOrg.",
      "most_likely_effort": 7
    },
    {
      "activity_id": "A12",
      "activity_name": "U6: Org ConfigGroup testing",
      "activity_description": "Unit tests for ConfigGroup generation. Integration test: generate org with library and with cryptogen+configtxgen -printOrg, compare semantic equivalence (MSP config, policies, anchor peers).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A13",
      "activity_name": "U7: ConfigUpdate calculation (configtxlator compute_update)",
      "activity_description": "Reimplement configtxlator compute_update logic: given two ConfigEnvelope protos (base and modified), compute ConfigUpdate delta. Handle protobuf message comparison, field masking, and update message construction. Must handle all config types (orderer, application, consortiums).",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A14",
      "activity_name": "U7: ConfigUpdate calculation testing",
      "activity_description": "Unit tests with various config changes. Integration test: compare library output with configtxlator compute_update for same inputs. Verify generated ConfigUpdate can be applied to base to produce modified config.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A15",
      "activity_name": "U8: Add org to consortium config update",
      "activity_description": "Implement function that takes system channel config, consortium name, and org ConfigGroup (from U6), produces ConfigUpdate adding org to consortium. Only modifies Consortiums group in system channel. Output unsigned channel update transaction.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A16",
      "activity_name": "U8: Consortium update testing",
      "activity_description": "Unit tests for consortium update. Integration test: apply generated update to system channel, verify new org appears in consortium. Compare with manual process (configtxgen -printOrg, protolator, configtxgen).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A17",
      "activity_name": "Library packaging, documentation, and CI",
      "activity_description": "Create Go module, define public API, write comprehensive documentation (README, godoc, usage examples). Set up CI pipeline with unit tests, integration tests (docker-compose Fabric network), and linting.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A18",
      "activity_name": "Code review, refactoring, and technical debt",
      "activity_description": "Peer code reviews for all changes. Refactor common protobuf manipulation utilities. Address edge cases discovered during integration testing. Ensure consistent error handling and logging.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 108
  }
}

